// Hum Kalaam everyday vocabulary, part 2: numbers, colours, family, health,
// food, places and transport, animals, weather, days, feelings and common
// verbs. Same notation, same conventions and the same status as part 1
// (lexicon-daily.js): authored from standard citation-form descriptions of ASL
// signs, checked geometrically by tests/lexicon.test.mjs, NOT yet reviewed by
// Deaf signers. Repeated movements (shakes, circles, taps) are approximated by
// a few key poses.
//
// An entry may list `forms`: other English spellings of the same sign
// (plurals, tenses, synonyms that share the ASL sign).

import { DAILY_SIGNS as D } from './lexicon-daily.js';

// ── notation helpers (as in part 1) ─────────────────────────────────────────

const at = (anchor, out = 0, up = 0, forward = 0) => ({ anchor, out, up, forward });
const sp = (out = 0.12, up = -0.02, forward = 0.26) => at('sternum', out, up, forward);
const H = (shape, where, fingers, palm, extra = {}) => ({ shape, at: where, fingers, palm, ...extra });
const T = (shape, touch, fingers, palm, extra = {}) => ({ shape, touch, fingers, palm, ...extra });
const P = (t, spec, hold = 0) => ({ t, ...spec, ...(hold ? { hold } : {}) });
const move = (p, [o = 0, u = 0, f = 0]) => ({ ...p, out: (p.out ?? 0) + o, up: (p.up ?? 0) + u, forward: (p.forward ?? 0) + f });

const chest = (out = 0, up = 0, part = 'palm') => ({ to: 'sternum', part, out, up, forward: 0.13 });
const chin = (out = 0, up = 0, part = 'fingertips', forward = 0.02) => ({ to: 'chin', part, out, up, forward });
const mouth = (part = 'fingertips', out = 0, up = 0) => ({ to: 'mouth', part, out, up, forward: 0.03 });
const temple = (part = 'fingertips', up = -0.04) => ({ to: 'forehead', part, out: 0.075, up, forward: 0.0 });
const brow = (part = 'fingertips', out = 0.02) => ({ to: 'forehead', part, out, up: -0.02, forward: 0.085 });
const cheek = (part = 'fingertips', up = 0.03) => ({ to: 'chin', part, out: 0.06, up, forward: 0.0 });

const BASE_PALM = H('FLAT', sp(0.06, -0.09, 0.24), ['forward', 'in'], 'up');
const WALL_PALM = H('FLAT', sp(0.0, -0.02, 0.27), ['up', 'forward'], 'in');
const BASE_FIST = H('S', sp(0.04, -0.08, 0.26), ['forward', 'in'], 'down');
const ARM_ACROSS = H('FLAT', sp(-0.02, -0.12, 0.27), ['in', 'forward'], 'down');
const BASE_INDEX = H('1', sp(0.04, -0.04, 0.27), 'up', 'in');
const BACK_HAND = H('FLAT', sp(0.04, -0.08, 0.27), ['forward', 'in'], 'down');

/** One hand moving through `places`, each phase built by `make(place)`. */
function path(make, places, { t = 0.3, step = 0.18, hold = 0.12 } = {}) {
	return places.map((pl, i) => P(i ? step : t, make(pl), i === places.length - 1 ? hold : 0));
}
/** Shake: start, then alternate +d / -d. */
const shakeAt = (p, d, n = 3) => [p, ...Array.from({ length: n }, (_, i) => move(p, i % 2 ? d.map((v) => -v) : d))];
/** A small circle in the front plane (out/up), back to the start. */
const circleAt = (p, r = 0.04) => [move(p, [0, r]), move(p, [r, 0]), move(p, [0, -r]), move(p, [-r, 0]), move(p, [0, r])];
/** A small circle in the flat plane (out/forward). */
const flatCircleAt = (p, r = 0.04) => [move(p, [0, 0, r]), move(p, [r, 0, 0]), move(p, [0, 0, -r]), move(p, [-r, 0, 0]), move(p, [0, 0, r])];
/** Two taps from `open` to `contact`. */
const tap2 = (open, contact, t = 0.16, hold = 0.12) => [P(0.3, open), P(t, contact), P(t, open), P(t, contact, hold)];

// A letter-handshape sign shaken (colours) or circled (days) at the side.
const letterShake = (shape, fingers = 'up', palm = 'forward') => path((pl) => ({ right: H(shape, pl, fingers, palm) }), shakeAt(sp(0.18, 0.06, 0.28), [0.03, 0, 0]), { step: 0.14 });
const letterCircle = (shape, fingers = 'up', palm = 'forward') => path((pl) => ({ right: H(shape, pl, fingers, palm) }), circleAt(sp(0.18, 0.08, 0.28)), { step: 0.16 });
const numberHold = (shape, palm = 'back') => [P(0.3, { right: H(shape, at('chin', 0.18, -0.06, 0.22), 'up', palm) }, 0.3)];
// A movement ending in the "person" marker: flat hands down the sides.
const PERSON_END = [P(0.28, { both: H('FLAT', sp(0.14, -0.02, 0.2), 'forward', 'in') }), P(0.28, { both: H('FLAT', sp(0.14, -0.26, 0.2), 'forward', 'in') }, 0.12)];

// ── the vocabulary ─────────────────────────────────────────────────────────

