	EIGHT: { gloss: 'Thumb touches the middle finger, palm out: the number eight.', phases: numberHold('8', 'forward') },
	NINE: { gloss: 'Thumb touches the index finger, palm out: the number nine.', phases: numberHold('9', 'forward') },
	TEN: { gloss: 'Thumbs-up hand shakes at the wrist: the number ten.', phases: letterShake('A', 'up', 'in') },

