	RED: { gloss: 'Index finger brushes down the lips twice.', phases: tap2({ right: H('1', at('mouth', 0.02, -0.06, 0.1), 'up', 'back') }, { right: T('1', mouth('indextip'), 'up', 'back') }) },
	BLUE: { gloss: 'B-hand shakes at the wrist.', phases: letterShake('B') },
