	BLACK: { gloss: 'Index finger draws across the forehead.', phases: [P(0.3, { right: T('1', brow('indextip', -0.05), 'in', 'down') }), P(0.3, { right: T('1', brow('indextip', 0.08), 'in', 'down') }, 0.12)] },
