	ORANGE: { gloss: 'Fist at the mouth squeezes twice, like squeezing an orange (colour and fruit).', phases: tap2({ right: H('C', at('mouth', 0.02, -0.02, 0.1), 'in', 'back') }, { right: H('S', at('mouth', 0.02, -0.02, 0.1), 'in', 'back') }), forms: ['ORANGES'] },
	BROWN: { gloss: 'B-hand slides down the cheek.', phases: [P(0.3, { right: T('B', cheek('edge', 0.04), 'up', 'in') }), P(0.3, { right: T('B', { to: 'chin', part: 'edge', out: 0.065, up: 0.0, forward: 0.02 }, 'up', 'in') }, 0.12)] },
