	GRANDMOTHER: { gloss: 'MOTHER (thumb on chin), then the hand arcs forward twice.', phases: [P(0.3, { right: T('5', chin(0, 0, 'thumbtip'), 'up', 'in') }), P(0.2, { right: H('5', at('chin', 0.04, -0.02, 0.16), ['up', 'forward'], 'in') }), P(0.2, { right: H('5', at('chin', 0.07, -0.04, 0.28), ['up', 'forward'], 'in') }, 0.12)], forms: ['GRANDMA', 'GRANDMOTHERS', 'NANI', 'DADI'] },
	GRANDFATHER: { gloss: 'FATHER (thumb on forehead), then the hand arcs forward twice.', phases: [P(0.3, { right: T('5', brow('thumbtip', 0), 'up', 'in') }), P(0.2, { right: H('5', at('forehead', 0.04, -0.03, 0.2), ['up', 'forward'], 'in') }), P(0.2, { right: H('5', at('forehead', 0.07, -0.05, 0.32), ['up', 'forward'], 'in') }, 0.12)], forms: ['GRANDPA', 'GRANDFATHERS', 'NANA', 'DADA'] },
