	DAUGHTER: { gloss: 'Flat hand from the jaw comes down to rest in the crook of the other arm.', phases: [P(0.3, { right: T('FLAT', chin(0.04, 0, 'fingertips'), ['up', 'in'], 'back') }), P(0.32, { left: H('FLAT', sp(0.04, -0.12, 0.26), ['in', 'forward'], 'up'), right: H('FLAT', sp(0.06, -0.08, 0.28), ['in', 'forward'], 'up') }, 0.14)], forms: ['DAUGHTERS'] },
