	PERSON: { gloss: 'P-hands move down the sides of the body.', phases: [P(0.3, { both: H('P', sp(0.14, 0.0, 0.22), 'forward', 'down') }), P(0.3, { both: H('P', sp(0.14, -0.24, 0.22), 'forward', 'down') }, 0.12)] },
