	SNAKE: { gloss: 'Bent-V hand spirals forward from the mouth.', phases: [P(0.3, { right: H('V', at('chin', 0.02, -0.02, 0.12), 'forward', 'down') }), P(0.2, { right: H('V', at('chin', 0.06, -0.06, 0.22), 'forward', 'down') }), P(0.2, { right: H('V', at('chin', 0.0, -0.1, 0.32), 'forward', 'down') }, 0.12)], forms: ['SNAKES'] },

	// Weather and nature
	WEATHER: { gloss: 'W-hands, palms facing, twist back and forth.', phases: [P(0.3, { both: H('W', sp(0.1, 0, 0.28), 'up', 'in') }), P(0.18, { both: H('W', sp(0.1, 0, 0.28), 'up', ['in', 'forward']) }), P(0.18, { both: H('W', sp(0.1, 0, 0.28), 'up', 'in') }, 0.12)] },
	SUN: { gloss: 'C-hand held up beside the head: the sun.', phases: [P(0.32, { right: H('C', at('forehead', 0.14, 0.1, 0.14), ['up', 'in'], 'forward') }, 0.24)], forms: ['SUNNY', 'SUNSHINE'] },
	MOON: { gloss: 'C-hand (thumb and index) at the side of the eye moves up: the crescent moon.', phases: [P(0.3, { right: H('C', at('nose', 0.08, 0.02, 0.1), 'up', 'in') }), P(0.26, { right: H('C', at('forehead', 0.12, 0.08, 0.12), 'up', 'in') }, 0.14)] },
	STAR: { gloss: 'Index fingers point up and brush up alternately.', phases: [P(0.3, { left: H('1', at('chin', 0.06, 0.04, 0.24), 'up', 'forward'), right: H('1', at('chin', 0.06, 0.1, 0.24), 'up', 'forward') }), P(0.2, { left: H('1', at('chin', 0.06, 0.1, 0.24), 'up', 'forward'), right: H('1', at('chin', 0.06, 0.04, 0.24), 'up', 'forward') }, 0.12)], forms: ['STARS'] },
	WIND: { gloss: 'Open hands sway side to side, like blowing wind.', phases: path((pl) => ({ both: H('5', move(sp(0.12, 0.04, 0.28), [pl.out, 0, 0]), 'up', 'forward') }), [{ out: 0 }, { out: 0.08 }, { out: -0.04 }, { out: 0.08 }], { step: 0.24 }), forms: ['WINDY'] },
	SNOW: { gloss: 'Open hands drift down with fingers wiggling.', phases: [P(0.3, { both: H('5', at('chin', 0.12, 0.04, 0.24), 'forward', 'down') }), P(0.24, { both: H('CLAW', at('chin', 0.12, -0.06, 0.24), 'forward', 'down') }), P(0.24, { both: H('5', at('chin', 0.12, -0.16, 0.24), 'forward', 'down') }, 0.12)], forms: ['SNOWING'] },
	CLOUD: { gloss: 'Curved hands circle beside the head, outlining a cloud.', phases: path((pl) => ({ both: H('CLAW', pl, 'up', 'forward') }), circleAt(at('forehead', 0.14, 0.04, 0.16), 0.04), { step: 0.16 }), forms: ['CLOUDS', 'CLOUDY'] },
