	FLOWER: { gloss: 'Flat-O fingertips touch under one side of the nose, then the other.', phases: [P(0.3, { right: T('FLAT_O', { to: 'nose', part: 'fingertips', out: 0.03, up: -0.02, forward: 0.06 }, ['back', 'up'], 'in') }), P(0.26, { right: T('FLAT_O', { to: 'nose', part: 'fingertips', out: -0.03, up: -0.02, forward: 0.06 }, ['back', 'up'], 'in') }, 0.14)], forms: ['FLOWERS'] },
	FIRE: { gloss: 'Open hands rise with fingers wiggling, like flames.', phases: [P(0.3, { both: H('5', sp(0.1, -0.12, 0.28), 'up', 'back') }), P(0.2, { both: H('CLAW', sp(0.1, -0.04, 0.28), 'up', 'back') }), P(0.2, { both: H('5', sp(0.1, 0.04, 0.28), 'up', 'back') }, 0.12)], forms: ['FIRES', 'BURN', 'BURNING'] },
	SKY: { gloss: 'Flat hand sweeps in an arc above the head.', phases: [P(0.3, { right: H('FLAT', at('forehead', -0.06, 0.14, 0.14), ['up', 'in'], 'forward') }), P(0.34, { right: H('FLAT', at('forehead', 0.2, 0.12, 0.14), ['up', 'out'], 'forward') }, 0.12)] },

	// Days and time
	MONDAY: { gloss: 'M-hand circles.', phases: letterCircle('M', 'up', 'back') },
	TUESDAY: { gloss: 'T-hand circles.', phases: letterCircle('T', 'up', 'back') },
	WEDNESDAY: { gloss: 'W-hand circles.', phases: letterCircle('W', 'up', 'back') },
	THURSDAY: { gloss: 'H-hand circles.', phases: letterCircle('H', 'up', 'back') },
	FRIDAY: { gloss: 'F-hand circles.', phases: letterCircle('F', 'up', 'back') },
	SATURDAY: { gloss: 'S-hand circles.', phases: letterCircle('S', 'up', 'back') },
	SUNDAY: { gloss: 'Both open hands, palms out, circle outward.', phases: path((pl) => ({ both: H('5', move(sp(0.12, 0.02, 0.3), [pl.out, pl.up, 0]), 'up', 'forward') }), [{ out: 0, up: 0 }, { out: 0.05, up: 0.03 }, { out: 0.08, up: -0.02 }, { out: 0.02, up: -0.04 }], { step: 0.18 }) },
