	PAST: { gloss: 'Flat hand moves back over the shoulder.', phases: [P(0.3, { right: H('FLAT', at('chin', 0.16, 0.0, 0.14), 'up', 'back') }), P(0.3, { right: H('FLAT', at('chin', 0.18, 0.04, -0.04), ['up', 'back'], 'back') }, 0.14)], forms: ['AGO'] },
	DAILY: { gloss: 'A-hand thumb slides forward along the cheek, repeatedly (every day).', phases: [P(0.3, { right: T('A', cheek('thumbtip', 0.02), 'up', 'in') }), P(0.18, { right: H('A', at('chin', 0.09, 0.0, 0.14), ['up', 'forward'], 'in') }), P(0.18, { right: T('A', cheek('thumbtip', 0.02), 'up', 'in') }), P(0.18, { right: H('A', at('chin', 0.09, 0.0, 0.14), ['up', 'forward'], 'in') }, 0.1)], forms: ['EVERYDAY'] },
	SOMETIMES: { gloss: 'Index finger arcs up off the flat palm, slowly, twice.', phases: [P(0.3, { left: BASE_PALM, right: T('1', { part: 'indextip', on: 'palm' }, 'down', 'back') }), P(0.3, { left: BASE_PALM, right: H('1', sp(0.08, 0.04, 0.24), 'up', 'back') }), P(0.3, { left: BASE_PALM, right: T('1', { part: 'indextip', on: 'palm' }, 'down', 'back') }, 0.12)] },
	OFTEN: { gloss: 'Bent fingertips tap the flat palm twice, quickly.', phases: tap2({ left: BASE_PALM, right: H('BENT_B', sp(0.06, 0.04, 0.24), ['down', 'forward'], 'down') }, { left: BASE_PALM, right: T('BENT_B', { part: 'fingertips', on: 'palm' }, ['down', 'forward'], 'down') }), forms: ['FREQUENTLY'] },

	// Common verbs
	DO: { gloss: 'Two C-hands move side to side together.', phases: path((pl) => ({ both: H('C', move(sp(0.12, -0.06, 0.28), [pl.out, 0, 0]), 'forward', 'down') }), [{ out: 0 }, { out: 0.06 }, { out: -0.02 }, { out: 0.06 }]), forms: ['DOES', 'DOING', 'DID'] },
