	HOPE: { gloss: 'Flat hand at the forehead and the other hand in front bend toward each other.', phases: [P(0.3, { left: H('FLAT', at('chin', 0.12, 0.04, 0.3), 'up', 'in'), right: H('FLAT', at('forehead', 0.1, -0.02, 0.12), 'up', 'out') }), P(0.24, { left: H('BENT_B', at('chin', 0.12, 0.04, 0.3), ['up', 'in'], 'in'), right: H('BENT_B', at('forehead', 0.1, -0.02, 0.12), ['up', 'out'], 'out') }, 0.14)], forms: ['HOPES', 'HOPED', 'HOPING'] },
	WISH: { gloss: 'C-hand moves down the chest.', phases: [P(0.3, { right: T('C', chest(0, 0.06, 'fingertips'), 'in', 'back') }), P(0.3, { right: T('C', chest(0, -0.08, 'fingertips'), 'in', 'back') }, 0.14)], forms: ['WISHES', 'WISHED'] },
