	CHOOSE: { gloss: 'F-hand picks from the fingers of the other hand and pulls back.', phases: [P(0.3, { left: H('V', sp(0.02, -0.02, 0.32), 'up', 'back'), right: T('F', { part: 'thumbtip', on: 'indextip' }, 'forward', 'in') }), P(0.26, { left: H('V', sp(0.02, -0.02, 0.32), 'up', 'back'), right: H('F', sp(0.08, -0.02, 0.2), 'forward', 'in') }, 0.12)], forms: ['CHOSE', 'CHOICE', 'SELECT', 'PICK'] },
	LOSE: { gloss: 'Flat-O hands, fingertips together, drop open.', phases: [P(0.3, { both: H('FLAT_O', sp(0.04, -0.02, 0.28), 'in', 'up') }), P(0.24, { both: H('5', sp(0.1, -0.08, 0.28), ['in', 'down'], 'down') }, 0.14)], forms: ['LOST', 'LOSING'] },
