	FIND: { gloss: 'Open hand above the other picks up something with thumb and index (F).', phases: [P(0.3, { left: BASE_PALM, right: H('5', sp(0.06, 0.02, 0.24), 'down', 'back') }), P(0.24, { left: BASE_PALM, right: H('F', sp(0.06, 0.1, 0.24), 'down', 'back') }, 0.14)], forms: ['FOUND', 'FINDS'] },
	SEARCH: { gloss: 'C-hand circles in front of the face.', phases: path((pl) => ({ right: H('C', pl, 'up', 'in') }), circleAt(at('nose', 0.04, 0, 0.18), 0.05), { step: 0.16 }), forms: ['SEARCHING', 'LOOKING'] },
	BREAK: { gloss: 'Two fists snap apart, like breaking a stick.', phases: [P(0.3, { both: H('S', sp(0.04, -0.04, 0.27), 'forward', 'down') }), P(0.18, { both: H('S', sp(0.12, -0.06, 0.27), ['forward', 'out'], 'down') }, 0.14)], forms: ['BROKE', 'BROKEN', 'BREAKS'] },
