	DRAW: { gloss: 'Little finger squiggles down the other palm.', phases: [P(0.3, { left: WALL_PALM, right: T('I', { part: 'fingertips', on: 'palm', up: 0.04 }, 'in', 'back') }), P(0.18, { left: WALL_PALM, right: T('I', { part: 'fingertips', on: 'palm', up: 0.0, forward: 0.02 }, 'in', 'back') }), P(0.18, { left: WALL_PALM, right: T('I', { part: 'fingertips', on: 'palm', up: -0.04 }, 'in', 'back') }, 0.12)], forms: ['DRAWING', 'DREW', 'ART'] },
	LAUGH: { gloss: 'L-hands brush up the sides of the mouth, smiling.', phases: tap2({ face: 'pleasant', both: T('L', { to: 'chin', part: 'indextip', out: 0.05, up: 0.0, forward: 0.0 }, 'in', 'back') }, { face: 'pleasant', both: T('L', { to: 'chin', part: 'indextip', out: 0.06, up: 0.04, forward: 0.0 }, 'in', 'back') }), forms: ['LAUGHING', 'LAUGHED'] },
