	SMILE: { gloss: 'Fingertips trace up from the corners of the mouth.', phases: [P(0.3, { face: 'pleasant', both: T('FLAT', mouth('fingertips', 0.03), 'up', 'back') }), P(0.26, { face: 'pleasant', both: T('FLAT', { to: 'chin', part: 'fingertips', out: 0.06, up: 0.05, forward: 0.0 }, 'up', 'back') }, 0.14)], forms: ['SMILING', 'SMILED'] },
