	HUG: { gloss: 'Crossed arms hug the body.', phases: [P(0.36, { face: 'pleasant', left: T('S', chest(-0.12, 0.02, 'thumbtip'), ['up', 'in'], 'back'), right: T('S', chest(-0.12, -0.04, 'thumbtip'), ['up', 'in'], 'back') }, 0.28)], forms: ['HUGS', 'HUGGED', 'EMBRACE'] },
	MISS: { gloss: 'Index finger touches the chin, with a sad face.', phases: [P(0.3, { face: 'concern', right: T('1', chin(0, 0, 'indextip'), ['up', 'back'], 'in') }, 0.24)], forms: ['MISSED', 'MISSING'] },
	WORRY: { gloss: 'Flat hands circle alternately in front of the forehead.', phases: [P(0.3, { face: 'concern', left: H('FLAT', at('forehead', 0.06, 0.0, 0.2), ['up', 'in'], 'back'), right: H('FLAT', at('forehead', 0.06, -0.06, 0.24), ['up', 'in'], 'back') }), P(0.2, { face: 'concern', left: H('FLAT', at('forehead', 0.06, -0.06, 0.24), ['up', 'in'], 'back'), right: H('FLAT', at('forehead', 0.06, 0.0, 0.2), ['up', 'in'], 'back') }), P(0.2, { face: 'concern', left: H('FLAT', at('forehead', 0.06, 0.0, 0.2), ['up', 'in'], 'back'), right: H('FLAT', at('forehead', 0.06, -0.06, 0.24), ['up', 'in'], 'back') }, 0.12)], forms: ['WORRIED', 'WORRYING', 'ANXIOUS'] },
	CARE: { gloss: 'K-hands, one on top of the other, circle together.', phases: path((pl) => ({ left: H('K', move(sp(0.04, -0.08, 0.27), [pl.out, 0, pl.forward]), 'forward', 'in'), right: H('K', move(sp(0.04, -0.02, 0.27), [pl.out, 0, pl.forward]), 'forward', 'in') }), [{ out: 0, forward: 0.03 }, { out: 0.03, forward: 0 }, { out: 0, forward: -0.03 }, { out: -0.03, forward: 0 }]) },
